package com.fireplatform;

import com.fasterxml.jackson.databind.*;
import com.fireplatform.shared.*;
import com.fireplatform.simembedded.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class SimEmbeddedInputsTest {
    final ObjectMapper json=new ObjectMapper().setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).enable(DeserializationFeature.USE_BIG_INTEGER_FOR_INTS).enable(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS);
    final SimEmbeddedInputs inputs=new SimEmbeddedInputs(json);
    Map<String,Object> body(){var m=new LinkedHashMap<String,Object>();m.put("device_id","legacy-device");m.put("iccid",null);m.put("carrier_name","");m.put("replaceability","UNKNOWN");m.put("management_party","UNKNOWN");m.put("fee_responsibility","UNKNOWN");m.put("reported_operator_status","UNKNOWN");m.put("expires_on",null);m.put("evidence_at",null);m.put("source_note","");m.put("expected_profile_revision",0L);m.put("reason","");return m;}
    SimEmbeddedInputs.Command parse(Map<String,Object> body)throws Exception{return inputs.command(json.writeValueAsBytes(body));}
    void bad(org.assertj.core.api.ThrowableAssert.ThrowingCallable work){assertThatThrownBy(work).isInstanceOfSatisfying(ApiError.class,e->{assertThat(e.status).isEqualTo(400);assertThat(e.code).isEqualTo("INVALID_REQUEST");assertThat(e.getMessage()).doesNotContain("SECRET");});}
    @Test void allThirteenFieldsAreRequiredAndOnlyIccidAndTwoDatesAllowNull()throws Exception{assertThat(body()).hasSize(12);assertThat(parse(body()).iccid()).isNull();for(String key:body().keySet()){var missing=body();missing.remove(key);bad(()->parse(missing));if(!Set.of("iccid","expires_on","evidence_at").contains(key)){var nil=body();nil.put(key,null);bad(()->parse(nil));}}}
    @Test void unknownReadOnlyAndCrossDomainKeysAreNotAccepted(){for(String key:List.of("installation_form","information_source","tenant_id","revision","recorded_at","card_id","changed","issued_to")){var extra=body();extra.put(key,"SECRET");bad(()->parse(extra));}}
    @Test void textEnumsAndNullableFieldsNeverCoerceScalarTypes(){for(String key:body().keySet())if(!key.equals("expected_profile_revision"))for(Object value:List.of(1,true,List.of("x"),Map.of("x",1))){var m=body();m.put(key,value);bad(()->parse(m));}}
    @Test void revisionsRejectRawNegativeZeroDecimalExponentStringUnsafeAndNegative()throws Exception{String valid=json.writeValueAsString(body());for(String raw:List.of("-0","-1","0.0","0e0","\"0\"","true","9007199254740992","9223372036854775808"))bad(()->inputs.command(valid.replace("\"expected_profile_revision\":0","\"expected_profile_revision\":"+raw).getBytes(StandardCharsets.UTF_8)));}
    @Test void revisionsKeepZeroAndMaximumSafeIntegerExact()throws Exception{assertThat(parse(body()).expectedProfileRevision()).isZero();var m=body();m.put("expected_profile_revision",SimEmbeddedInputs.MAX_SAFE);assertThat(parse(m).expectedProfileRevision()).isEqualTo(SimEmbeddedInputs.MAX_SAFE);}
    @Test void duplicateTrailingMalformedAndNonObjectRootsFail()throws Exception{String valid=json.writeValueAsString(body());for(String raw:List.of("null","[]","{}",valid+" {}",valid.substring(0,valid.length()-1)+",\"reason\":\"SECRET\"}",valid.replace("legacy-device","bad\\q")))bad(()->inputs.command(raw.getBytes(StandardCharsets.UTF_8)));}
    @Test void deviceIdsAreExactOpaqueStringsWithNbspBomAndNoUnicodeNormalization(){for(String id:List.of("legacy-device","000123","Ａ１２","device/opaque?%#","\u00a0id\u00a0","\ufeffid\ufeff","\u3000id\u3000"))assertThat(SimEmbeddedInputs.device(id)).isEqualTo(id);assertThat(SimEmbeddedInputs.device("Case")).isNotEqualTo(SimEmbeddedInputs.device("case"));}
    @Test void deviceJavaTrimEdgesAreRejectedRatherThanNormalized(){for(String id:List.of(" id","id ","  ","\tid","id\n"))bad(()->SimEmbeddedInputs.device(id));}
    @Test void deviceControlsNullEmptyAndBadUtf16Fail(){for(String id:Arrays.asList(null,"","a\u0000b","a\tb","a\u007fb","a\u0085b","\ud800","\udc00"))bad(()->SimEmbeddedInputs.device(id));}
    @Test void deviceLimitUsesUtf16Units(){assertThat(SimEmbeddedInputs.device("😀".repeat(32))).hasSize(64);bad(()->SimEmbeddedInputs.device("😀".repeat(33)));}
    @Test void nullableIccidIsUnknownAndKnownIdentifierRetainsLeadingZerosCaseAndWidth(){assertThat(SimEmbeddedInputs.iccid(null)).isNull();assertThat(SimEmbeddedInputs.iccid(" 000Ａbc ")).isEqualTo("000Ａbc");assertThat(SimEmbeddedInputs.iccid("x".repeat(64))).hasSize(64);for(String raw:List.of(""," ","x".repeat(65),"x\nx","\ud800"))bad(()->SimEmbeddedInputs.iccid(raw));}
    @Test void carrierAndNoteUseOldManualInputSemanticsWithoutOldBusinessImports(){assertThat(SimEmbeddedInputs.carrier("  manual carrier  ")).isEqualTo("manual carrier");assertThat(SimEmbeddedInputs.note(" \r\nA\tB\n ")).isEqualTo("A\tB");assertThat(SimEmbeddedInputs.carrier(" ")).isEmpty();assertThat(SimEmbeddedInputs.note(" ")).isEmpty();bad(()->SimEmbeddedInputs.carrier("x".repeat(201)));bad(()->SimEmbeddedInputs.note("x".repeat(1001)));bad(()->SimEmbeddedInputs.carrier("a\tb"));bad(()->SimEmbeddedInputs.note("a\u0000b"));}
    @Test void fourManualAxesAreIndependentAndClosed(){for(String choice:SimEmbeddedInputs.REPLACEABILITY)assertThat(SimEmbeddedInputs.choice(choice,SimEmbeddedInputs.REPLACEABILITY)).isEqualTo(choice);for(String choice:SimEmbeddedInputs.PARTY)assertThat(SimEmbeddedInputs.choice(choice,SimEmbeddedInputs.PARTY)).isEqualTo(choice);for(String key:List.of("replaceability","management_party","fee_responsibility","reported_operator_status")){var m=body();m.put(key,"unknown");bad(()->parse(m));}}
    @Test void expiryIsStrictGregorianDateNotTimestampOrInferredMidnight(){for(String value:List.of("0001-01-01","2024-02-29","9999-12-31"))assertThat(SimEmbeddedInputs.date(value)).isEqualTo(value);assertThat(SimEmbeddedInputs.date(null)).isNull();for(String value:List.of("0000-01-01","2026-02-29","2026-1-01","2026-01-01T00:00:00Z"," 2026-01-01"))bad(()->SimEmbeddedInputs.date(value));}
    @Test void evidenceNormalizesOnlyValidUtcMicrosecondsAndPreservesPrecision(){assertThat(SimEmbeddedInputs.evidence("2026-01-02T03:04:05.1Z")).isEqualTo("2026-01-02T03:04:05.100000Z");assertThat(SimEmbeddedInputs.evidence("0001-01-01T00:00:00Z")).isEqualTo("0001-01-01T00:00:00.000000Z");assertThat(SimEmbeddedInputs.evidence("9999-12-31T23:59:59.123456Z")).endsWith(".123456Z");for(String value:List.of("2026-01-02T03:04:05+00:00","2026-01-02T03:04:05.1234567Z","2026-01-02T24:00:00Z","0000-01-01T00:00:00Z","12345","2026-01-02"))bad(()->SimEmbeddedInputs.evidence(value));}
    @Test void reasonPreservesOriginalEdgesAndLegalControlsInsteadOfSharingNoteNormalization(){for(String reason:List.of(""," "," \r\n\ta\t\r\n ","\u00a0","<literal>&text"))assertThat(SimEmbeddedInputs.reason(reason)).isEqualTo(reason);for(String reason:Arrays.asList(null,"a\u0000b","\u000b","\u001f","\u007f","\u0085","\ud800"))bad(()->SimEmbeddedInputs.reason(reason));}
    @Test void reasonAndNotesCountExistingUtf16TechnicalBounds(){assertThat(SimEmbeddedInputs.reason("😀".repeat(500))).hasSize(Limits.MAX_CHANGE_REASON_LENGTH);bad(()->SimEmbeddedInputs.reason("😀".repeat(501)));assertThat(SimEmbeddedInputs.note("😀".repeat(500))).hasSize(Limits.SIM_CARD_SOURCE_NOTE_MAX);}
    @Test void actorConfirmationPasswordFieldIsRejected()throws Exception{var m=body();m.put("actor_password","Synthetic-Confirmation-Password");bad(()->parse(m));}
    @Test void pagingRejectsNonCanonicalIntegersWithoutCoercion(){assertThat(SimEmbeddedInputs.page(null,1)).isEqualTo(1);assertThat(SimEmbeddedInputs.page("1000000",1)).isEqualTo(1000000);for(String raw:List.of("-0","01","1e0","1.0","2147483648",""))bad(()->SimEmbeddedInputs.page(raw,1));}
    @Test void canonicalFingerprintIsNullableSafeOrderedAndExcludesPassword()throws Exception{var m=body();m.put("reason"," reason ");var command=parse(m);var expected=Arrays.asList("tenant-a","sim-embedded-record","legacy-device",0L,null,"","UNKNOWN","UNKNOWN","UNKNOWN","UNKNOWN",null,null,""," reason ");assertThat(SimEmbeddedCommands.fingerprint("tenant-a",command)).isEqualTo(expected);assertThat(json.writeValueAsString(expected)).doesNotContain("recorded_at");}
}
